use std::str::FromStr;

use identus_did_core::ResolutionResult;
use midnight_did::did::MidnightDid;
use midnight_did::dlt::{ContractState, ContractStateDeserializer};
use serde_json::Value;

const DID: &str = "did:midnight:undeployed:02002faa3feaead86ae445622b5806ddd6da8e423992851b30a6f24b4aa8072a5c64";

const CONTRACT_STATES: [&str; 10] = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
];

#[test]
fn test_midnight_serde_rs() {
    use midnight_did_serde::DefaultContractStateDeserializer;

    let expected_did_docs = serde_json::from_str::<Vec<Value>>(include_str!("./did-documents.json")).unwrap();

    let deserializer = DefaultContractStateDeserializer;
    let did = MidnightDid::from_str(DID).unwrap();
    let did_docs = CONTRACT_STATES
        .iter()
        .map(|contract_state| {
            let state = ContractState::from_str(contract_state).unwrap();
            let (metadata, did_doc) = deserializer.deserialize(&did, &state).unwrap();
            let resolution_result = ResolutionResult {
                did_document_metadata: metadata,
                did_document: Some(did_doc),
                did_resolution_metadata: Default::default(),
            };
            let did_doc_json = serde_json::to_value(&resolution_result).unwrap();
            did_doc_json
        })
        .collect::<Vec<_>>();

    // eprintln!("{}", serde_json::to_string_pretty(&did_docs).unwrap());
    assert_eq!(did_docs, expected_did_docs);
}
